#include "goal1_native_endpoint.hpp"
#include <iostream>
#include <iomanip>
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int index,status=0;Real epsilon,t,x[3];try{while(std::cin>>index>>epsilon>>t>>x[0]>>x[1]>>x[2]){
 namespace cs=cubed_sphere;namespace ne=cs::native_endpoint;namespace h=z4c::hyperboloidal;h::Z4cJet<Real>empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){Real a;if(!(std::cin>>a))throw std::runtime_error("short native fixture");return a;});Real target[22],first[13][3];for(Real&a:target)std::cin>>a;for(auto&v:first)for(Real&a:v)std::cin>>a;if(!std::cin)throw std::runtime_error("short native targets");h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);auto result=ne::Evaluate(u,p,x);auto changed=ne::Evaluate(u,p,x,.123);auto omitted=ne::Evaluate(u,p,x,0,true);Real error=0,first_error=0,invariance=0;
 auto scaled=[](Real a,Real b){return std::abs(a-b)/std::max({Real(1),std::abs(a),std::abs(b)});};for(int n=0;n<22;++n){error=std::max(error,scaled(result.rhs[n],target[n]));invariance=std::max(invariance,std::abs(result.rhs[n]-changed.rhs[n]));}for(int n=0;n<13;++n)for(int d=0;d<3;++d){first_error=std::max(first_error,scaled(result.first[n][d],first[n][d]));invariance=std::max(invariance,std::abs(result.first[n][d]-changed.first[n][d]));}invariance=std::max(invariance,std::abs(result.pole_time-changed.pole_time));auto bad=u;bad.trace.value+=.001;bool rejected=!ne::Evaluate(bad,p,x).valid;
 std::cout<<"{\"case\":"<<index<<",\"epsilon\":"<<epsilon<<",\"time\":"<<t<<",\"valid\":"<<(result.valid?"true":"false")<<",\"native22_rhs_scaled\":"<<error<<",\"native13_rhs_spatial_scaled\":"<<first_error<<",\"pole_value_absolute\":"<<result.pole<<",\"pole_tangent_absolute\":"<<result.tangent<<",\"pole_second_compatibility_absolute\":"<<result.second<<",\"native22_pole_time_absolute\":"<<result.pole_time<<",\"nullness_time_absolute\":"<<result.nullness_time<<",\"Z_time_absolute\":"<<result.z_time<<",\"unused_higherjet_invariance_absolute\":"<<invariance<<",\"omitted_metric_gradient_time_pole_absolute\":"<<omitted.pole_time<<",\"omitted_metric_gradient_time_Z_absolute\":"<<omitted.z_time<<",\"invalid_trace_pole_rejected\":"<<(rejected?"true":"false")<<",\"native_rhs\":[";for(int n=0;n<22;++n)std::cout<<(n?",":"")<<result.rhs[n];std::cout<<"]}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;status=2;}Kokkos::finalize();return status;}
